const boneWolfSheet=new Image();boneWolfSheet.assetSrc='assets/bone-wolf-v2.png';
function beginBoneWolf(e){let angle=Math.atan2(p.y-e.y,p.x-e.x),origin={x:e.x,y:e.y},lanes=[-25,25,0].map(offset=>{let a=angle+offset*Math.PI/180,length=0;for(let d=6;d<=300;d+=6){let q={x:origin.x+Math.cos(a)*d,y:origin.y+Math.sin(a)*d};if(!passable(q.x,q.y,0)||!lineClear(origin,q))break;length=d;}return {angle:a,length};});e.state='attack';e.elapsed=0;e.struck=false;e.facing=Math.cos(angle)-Math.sin(angle)<0?-1:1;e.attack={pattern:'boneRibSalvo',bespoke:true,windup:1.8,origin,lanes,ribs:3,fired:false};}
function boneWolfLaneContains(origin,lane,point){let dx=point.x-origin.x,dy=point.y-origin.y,along=dx*Math.cos(lane.angle)+dy*Math.sin(lane.angle),side=-dx*Math.sin(lane.angle)+dy*Math.cos(lane.angle);return along>=24&&along<=lane.length+1e-8&&Math.abs(side)<=18+1e-8;}
const boneWolfHitBase=hit;hit=(e,d)=>{let a=e.attack,hp=e.hp,direct=!e.dotTick,result=boneWolfHitBase(e,d);if(e.species==='r10e0'&&direct&&e.hp>0&&e.hp<hp&&e.attack===a&&a?.pattern==='boneRibSalvo'&&!a.fired&&a.ribs>0){a.ribs--;playSound('impact',e.x,e.y);}return result;};
const boneWolfAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r10e0')return boneWolfAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='boneRibSalvo'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=270&&clear){beginBoneWolf(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.6;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,112*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,22)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.fired&&e.elapsed>=1.8){a.fired=true;e.struck=true;if(a.lanes.slice(3-a.ribs).some(lane=>boneWolfLaneContains(a.origin,lane,p))&&lineClear(a.origin,p))hurt(72);if(a.ribs)playSound('impact',e.x,e.y);}
 if(e.elapsed>=2.8){e.attack=null;e.state='idle';e.t=2.6;}
};
const boneWolfDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r10e0'||!boneWolfSheet.complete||!boneWolfSheet.naturalWidth||!boneWolfSheet.naturalHeight)return boneWolfDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='boneRibSalvo')f={row:2,col:e.elapsed<.5?0:e.elapsed<1.8?1:e.elapsed<2.1?2:3};let q=project(e.x,e.y),sw=boneWolfSheet.naturalWidth/4,sh=boneWolfSheet.naturalHeight/3,w=235,h=w*sh/sw,anchor=[[.82,.82,.82,.82],[.78,.67,.81,.77],[.76,.82,.79,.78]][f.row][f.col];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,boneWolfSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(boneWolfSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const boneWolfSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r10e0'?165:boneWolfSizeBase(e);
const boneWolfGroundBase=drawGroundEffects;drawGroundEffects=()=>{boneWolfGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r10e0'):enemies)){let a=e.attack;if(e.species!=='r10e0'||e.hp<=0||a?.pattern!=='boneRibSalvo'||!visibleAt(e.x,e.y)||e.elapsed>=2.1)continue;let q=project(a.origin.x,a.origin.y);ctx.save();ctx.translate(q.x,q.y);ctx.transform(ISOX,ISOY,-ISOX,ISOY,0,0);for(let i=3-a.ribs;i<3;i++){let lane=a.lanes[i];if(lane.length<24)continue;ctx.save();ctx.rotate(lane.angle);ctx.fillStyle=a.fired?'#d6b9f077':'#c6a5e633';ctx.strokeStyle='#dcc9ee';ctx.lineWidth=2;ctx.beginPath();ctx.rect(24,-18,lane.length-24,36);ctx.fill();ctx.stroke();ctx.restore();}ctx.restore();if(!a.fired){ctx.save();ctx.strokeStyle='#f5ead7';ctx.lineWidth=3;for(let i=0;i<a.ribs;i++){let x=q.x+(i-(a.ribs-1)/2)*12;ctx.beginPath();ctx.moveTo(x-3,q.y-75);ctx.lineTo(x+3,q.y-87);ctx.stroke();}ctx.restore();}}};

if(typeof registerDirectEnemy==='function')registerDirectEnemy('r10e0',animateEnemy,drawRegionEnemy);
